      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크)민간 아이돌보미서비스 이용 부모님 설문조사-민간 아이돌봄서비스를 자부담으로 이용 중인 분 20대\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.23. 14:13\n조회 26\n구독\n고유링크)민간 아이돌보미서비스 이용 부모님 설문조사-민간 아이돌봄서비스를 자부담으로 이용 중인 분 20대\n제목: (4만원 상당 답례품) 민간 아이돌보미서비스 이용 부모님 설문조사\n육아정책연구소 주관으로, 민간 아이돌보미를 이용하는 부모님들 대상으로 설문조사를 진행합니다.\n민간 아이돌보미서비스 이용 현황과 지원에 대한 요구를 파악하여, 향후 정부지원 아이돌보미서비스 정책 개선을 위한 자료로 활용하고자 연구를 수행하고 있습니다.\n아래 조건에 해당하시는 분들의 많은 지원을 부탁드립니다.\n<참가조건>\n아래 조건에 모두 해당하는 분\n1) 민간 아이돌봄서비스를 자부담으로 이용 중인 분\n2) 맞벌이 가구 또는 취업 중인 한부모 가구의 어머니·아버지\n3) 민간 아이돌봄서비스를 이용하는 자녀 중 막내가 초등학교 6학년 이하인 분\n4) 추후(11월 중) 온라인 좌담회에 참여할 의향이 있는 분\n※ 민간 아이돌봄서비스란 업체·플랫폼을 통한 이용, 개인적으로 구한 베이비시터 모두 포함합니다.\n<참가 신청>\n아래 링크로 사전 설문에 응답해 주세요.\nhttps://www.research.net/r/fgi_cafe_2_cqrtgb\n<참여 절차>\n사전 설문 제출 후 본설문 참여자로 선정되시면, 설문 링크를 보내드립니다(본설문 참여완료시 4만원 상당 모바일상품권 지급).\n본설문에 참여하신 분들 중, 온라인 좌담회까지 참여하시면 8만원이 추가로 지급됩니다.\n※ 참가자 선정을 위해 증빙자료(민간아이돌보미서비스 이용내역 등)를 요청드릴 수 있습니다.\n좋아요\n2\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크)민간 아이돌보미서비스 이용 부모님 설문조사-민간 아이돌봄서비스를 자부담으로 이용 중인 분 30대\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n고유링크)민간 아이돌보미서비스 이용 부모님 설문조사-민간 아이돌봄서비스를 자부담으로 이용 중인 분 20대\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n11/3~9) 기업의 IT 및 AI 서비스(ChatGPT 등) 이용·도입 경험 인터뷰-여성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n1\n11/3~9) 기업의 IT 및 AI 서비스(ChatGPT 등) 이용·도입 경험 인터뷰-남성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n2\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
