      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n26~59세 남여 )정수기 이용자 및 구매담당자 워크샵-여성\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.23. 16:44\n조회 69\n구독\n26~59세 남여 )정수기 이용자 및 구매담당자 워크샵\n가정에 2025년 10월 이후 정수기설치하여 이용하신 분들/ 정수기 구매계약 담당자와 같이 11월 초에 워크샵 진행예정입니다.\n1.대상 : 수도권에 사는 26~59세 남여 중, 최근 1년 내(2025년 10월 기준) 정수기 직접사용자 및 정수기 구매계약 담당자(정수기미사용자도 가능)\n보유브랜드: 삼성/LG/코웨이/쿠쿠/SK매직 만 해당\n2.사전과제 및 워크샵 총사례비 : 150,000원(현금지급, 사전과제만 했을 경우 지급이 어려움)\n주말토요일 10시-16시까지 워크샵진행\n*카운터탑 정수기 예시 / 수돗물 직수가 아닌 정수기\n이용자 예시)\n1. 이름/성별 : ex)홍길동 / 여\n2. 생년월일 : ex)850215\n3. 연락처 :\n4. 거주지역:\n5. 최근 1년 내 카운터탑 정수기 설치 브랜드명 : 1) 삼성 2) LG 3) 코웨이 4) 쿠쿠 5) SK매직\n6. 설치년월(2025년 10월이후) : 년 월\n7. 정수기유형: 1) 얼음정수기 / 2) 얼음이 안나오는 정수기\n8. 구매방식: 1)구매(일시불) 2) 구매(할부) 3)렌탈 및 구독\n9. 정수기 관리방식: 1) 셀프관리 2)방문관리\n10. 이용중인 정수기 불만사항여부: 예\n11. 결혼 및 자식유무 : 1) 미혼 2) 기혼(신혼) 3) 기혼(무자녀) 4) 기혼(유자녀)\n12. 반려동물 거주여부: 1)있음 ( 반려견 / 반려묘 / 기타( )) / 1) 없음\n13. 소개자명/소개자연락처:\n정수기 구매계약 담당자 예시\n1. 이름/성별 : ex)홍길동 / 여\n2. 생년월일 : ex)850215\n3. 연락처 :\n4. 거주지역:\n5. 직업: 정수기 구매 및 계약담당자\n6. 소개자명/ 소개자연락처\n**카운터탑 정수기- 예시 / 수돗물 직수가 아닌 정수기\nhttps://forms.gle/f4xQusGtBRifWbCu6\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n11/5) 만 25~44세 여성) 현재 꾸준하게 운동을 하고있는 여성분들 좌담회\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n26~59세 남여 )정수기 이용자 및 구매담당자 워크샵-여성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n26~59세 남여 )정수기 이용자 및 구매담당자 워크샵-남성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10/27~28) KR2/ KR4 구독서비스\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
