      "target_condition": "으로 하며, 사업자등록을 하고 활동하는 분과 사업자등록 없이 활동하는 분을 모두 모집합니다. 성별과 연령에는 제한이 없습니다.",
      "date": "10~11월 중, 참석자와 협의 후 확정 / 평일 저녁 및 주말 조율 가능",
      "time": "",
