      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10~11월 중) 이사서비스 사업주 및 현장 작업자 좌담회 -여성\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.23. 17:16\n조회 5\n구독\n10~11월 중) 이사서비스 사업주 및 현장 작업자 좌담회\n한국노동연구원에서 진행하는 이사서비스 사업주 및 현장 작업자 좌담회에 참석하실 분들을 소개받고자 연락드립니다.\n이번 조사는 이사서비스 종사자의 활동 경험과 일감을 구하는 과정, 작업 및 보수 지급 방식, 사회보험에 관한 의견을 듣고, 관련 제도 개선을 위한 기초자료를 마련하고자 진행합니다.\n직접 이사팀을 운영하면서 현장 작업에도 참여하는 사업주와, 고정된 팀 또는 여러 업체에서 작업하는 종사자를 모집합니다. 성별과 연령에는 제한이 없습니다.\n실제 수행 업무와 활동 형태, 경력 등을 확인해야 하므로, 신청해주신 분들과 저희가 직접 통화한 후 최종 참석자를 선정할 예정입니다.\n〈기본 정보〉\n- 좌담회명: 이사서비스 종사자의 활동 실태 및 사회보험 관련 FGI\n- 모집 대상: 포장이사 / 반포장이사 / 이삿짐 운반 / 포장 / 정리 등 이사 현장 작업에 직접 참여하는 사업주 및 작업자\n- 일정: 10~11월 중, 참석자와 협의 후 확정 / 평일 저녁 및 주말 조율 가능\n- 장소: 서울 지역 내 회의실\n- 사례비: 10만원\n- 소요시간: 2시간 내외\n〈기본 질문〉\n- 성명 / 성별 / 연령 / 휴대폰 번호 / 주 활동 지역(시/군/구)\n〈추가 질문〉\n1. 평소 이사 현장에서 어떤 방식으로 일하고 계십니까?\n- 직접 이사팀을 운영하면서 현장 작업에도 참여\n- 주로 고정된 이사팀에서 작업자로 활동(본방)\n- 고정된 팀 없이 여러 업체나 팀에서 건별로 작업(떴다)\n2. 이사 현장에서 주로 어떤 작업을 하십니까? (복수응답 가능)\n- 이사 견적 및 현장 관리\n- 이삿짐 운반 / 상하차\n- 이삿짐 포장\n- 주방정리 / 짐 정리\n- 기타\n3. 이사서비스 분야에서 일하신 기간은 얼마나 되셨습니까?\n4. 현재 하시는 일과 관련한 사업자등록 상태는 어떻게 됩니까?\n- 사업자등록을 한 적이 없음\n- 현재 등록되어 있음 / 등록 기간 5년 미만\n- 현재 등록되어 있음 / 등록 기간 5년 이상\n- 과거 등록했으나 현재는 폐업한 상태\n5. 평소 이사 일감은 주로 어떤 경로로 연결됩니까? (복수응답 가능)\n- 영구크린 / KGB 등 이사업체 또는 알선업체\n- 고정된 이사팀에서 배정\n- 인력사무소 / 구인구직 게시판\n- 숨고 / 짐싸 등 플랫폼\n- SNS / 블로그 등 마케팅\n- 기존 고객 / 지인 소개\n- 기타\n6. 최근에는 평균적으로 한 달에 며칠 정도 이사 작업을 하십니까?\n- 월 12일 미만\n- 월 12~14일\n- 월 15일 이상\n7. 이사서비스 일로 얻는 월평균 수입은 어느 정도입니까?\nhttps://forms.gle/DweDRGYf8LJAQ9zbA\n좋아요\n0\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10~11월 중) 가사·간병 종사자 좌담회-20대 이상 남녀\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10~11월 중) 이사서비스 사업주 및 현장 작업자 좌담회 -여성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10~11월 중) 이사서비스 사업주 및 현장 작업자 좌담회 -남성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10~11월 중)입주청소 / 정리수납 / 줄눈시공 / 집수리 등 방문 작업 종사자 좌담회-여성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
