      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10~11월 중) 가사·간병 종사자 좌담회-20대 이상 남녀\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.23. 17:30\n조회 17\n구독\n10~11월 중) 가사·간병 종사자 좌담회-20대 이상 남녀\n신청하신분은 재신청 안하셔도 됩니다\n현재 추가 모집을 진행하고 있으며, 특히 아래와 같은 플랫폼을 통해 일감을 구해 일하시는 가사/간병 종사자분들을 추가로 모집하고 있습니다.\n가사: 청소연구소, 미소의집, 대리주부, 홈마스터 등\n간병: 케어네이션, 케어닥, 케어드림 등\n이번 조사는 가사·간병 종사자의 일감 확보 방식, 근무 및 소득 실태, 사회보험에 대한 의견을 듣고 제도 개선을 위한 기초자료를 마련하고자 진행합니다.\n총 모집 인원은 27명(가사 11명, 간병 16명)이며, 성별과 연령에는 제한이 없습니다.\n일감을 구하는 방식 등 세부 조건을 확인해야 하므로, 소개해주신 분들과 저희가 직접 통화한 후 최종 참석자를 선정할 예정입니다.\n좌담회 기본 정보와 신청 시 확인을 부탁드리는 항목은 아래와 같습니다.\n〈기본 정보〉\n좌담회명: 가사/간병 종사자의 근무 경험 및 사회보험 관련 FGI\n필수 조건: 플랫폼·소개소·지인 소개 등을 통해 일감을 구하거나, 이용자와 직접 협의하여 가사 또는 간병 일을 하고 계신 분\n※ 가사의 경우, 기관에 직원으로 직접 고용된 분과 아이돌봄만 하시는 분은 제외됩니다.\n일정: 10~11월 중, 참석자와 협의 후 확정\n장소: 서울 지역 내 회의실\n사례비: 10만원\n소요시간: 2시간 내외\n〈기본 질문〉\n성명 / 성별 / 연령대 / 직업 / 휴대폰 번호\n〈추가 질문〉\n현재 하고 계신 일: 가사 / 간병 / 둘 다\n주로 일감을 구하는 경로: 앱·플랫폼 / 소개소·기관·업체 / 지인 소개 / 이용자·보호자와 직접 거래 / 기타\n이용하는 앱·플랫폼 또는 소개소·기관·업체의 이름(해당하는 경우)\n최근 3개월 동안 가사 또는 간병 일로 얻은 월평균 소득\nhttps://forms.gle/xBbh34buaxybWr9S8\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/28~11/3) 피부미용(리프팅 시술) 경험자(40-65세 여성/60~65세 급) 좌담회 모집\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10~11월 중) 가사·간병 종사자 좌담회-20대 이상 남녀\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10~11월 중) 이사서비스 사업주 및 현장 작업자 좌담회 -여성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n10~11월 중) 이사서비스 사업주 및 현장 작업자 좌담회 -남성\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
