      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/28~11/3) 피부미용(리프팅 시술) 경험자(40-65세 여성/60~65세 급) 좌담회 모집\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.23. 17:34\n조회 34\n구독\n10/28~11/3) 피부미용(리프팅 시술) 경험자(40-65세 여성/60~65세 급) 좌담회 모집\n신청하신분은 재신청 안하셔도 됩니다\n특히 울쎄라 시술 경험자 & 콜라겐 부스터 비경험자 등 아직 많은 신청필요합니다!\n▶<울쎄라 4회이상 경험자>부족합니다◀\n공통조건\n** 울쎄라(리프팅 시술) 경험자 & 콜라겐 부스터 경험 혹은 비경험 (의향자) 40-65세 여성 <직업, 결혼여부, 지역 무관>\n▶공통조건\n1) 서울 및 수도권 거주하는 40-65세 여성<직업, 결혼여부, 지역 무관>\n2) 최근 3년 내 피부과/성형외과(전문병원)에서 울쎄라 시술경험자(피부 미용 목적)\n→울쎄라 4회이상 시술경험자(연 1회 이상 정기 시술) or 울쎄라 1-3회 시술경험자<최근 시술경험자 우선 선정>\n3) 평소 다양한 방번으로 피부 관린하는 분(기능성 화장품, 홈케어기기, 에스테딕, 병원시술 등)\n4) 콜라겐 부스터 향후 시술의향자\n**반영구/단순 피부 마사지, 질병 치료 목적/다이어트 지방흡입은 미용시술에서 제외\n▶시술 브랜드\n* 콜라겐 부스터 시술명- 레디어스, 스컬트라, 쥬베룩 볼륨, 울트라콜, 올리디아, 엘란쎄,PRP,PRF(자가혈 콜라겐부스터),엑소좀 등\n* 스킨부스터 시술명- 벨로테로, 리쥬란, 쥬베룩, 스킨바이브, 바이리즌, 레스틸렌,백옥주사, RDRN등\n* 보톡스 시술명- 제오민, 엘러간, 리스톡스, 코어톡스, 보툴렉스,나보타, 뉴럭스, 메디톡신, 디스포트등\n* 필러 시술명- 벨로테로, 쥬비덤, 채움(더채움),레스틸렌, 이브아르, 뉴라미스, 벨라스트, 엘라비에, 에피티그, 테오시알, 스타일리지등\n* 리프팅 시술명- 울쎄라, 써마지, 튠페이스, 슈링크, 더블로, 인보드, 올라지오,덴서티, 민트실, 코그실, PLLA, PDO,엑소좀, 수술-안면거상, 미니거상 등\n▶조사 일정&방식\n* 소요시간 2시간 30분(여의도역 부근 도보 10분 회사방문)\n* 사례비 8만원(좌담회 최종참석 이후 본인계좌이체-소득신고 및 개인정보입력 필수)\n* 좌담회 전/후 모바일 설문 있음\n* 좌담회 참석 3개월 후 설문 있음 (커피쿠폰 증정예정)\n그룹\n그룹 특성\n진행 시간(총 2시30분)\n사례비\nG1\n울쎄라 지금까지 총4회이상 경험자&콜라겐 부스터 경험자\n10/28(수) 15시~ (20분전 도착필수)\n8만원\nG2\n울쎄라 지금까지 총4회이상 경험자&콜라겐 부스터 경험자\n10/28(수) 18시~ (20분전 도착필수)\n8만원\nG3\n울쎄라 지금까지 총4회이상 경험자&콜라겐 부스터 비경험자\n10/29(목) 11시~ (20분전 도착필수)\n8만원\nG4\n울쎄라 지금까지 총4회이상 경험자&콜라겐 부스터 비경험자\n10/29(목) 15시~ (20분전 도착필수)\n8만원\nG5\n울쎄라 지금까지 총1-3회 경험자&콜라겐 부스터 경험자\n10/29(목) 18시~ (20분전 도착필수)\n8만원\nG6\n울쎄라 지금까지 총1-3회 경험자&콜라겐 부스터 경험자\n11/2(월) 11시~ (20분전 도착필수)\n8만원\nG7\n울쎄라 지금까지 총1-3회 경험자&콜라겐 부스터 비경험자\n11/2(월) 15시~ (20분전 도착필수)\n8만원\nG8\n울쎄라 지금까지 총1-3회 경험자&콜라겐 부스터 비경험자\n11/3(화) 11시~ (20분전 도착필수)\n8만원\nG9\n울쎄라 지금까지 총1-3회 경험자&콜라겐 부스터 비경험자\n11/3(화) 15시~ (20분전 도착필수)\n8만원\nG10\n울쎄라 지금까지 총1-3회 경험자&콜라겐 부스터 비경험자\n11/3(화) 18시~ (20분전 도착필수)\n8만원\n▶진행과정\n** 1단계: 대상자 선정통화(20분내외) → 2단계: 참여확정연락 → 3단계: 당일 최종 참석 **\n▶(신청)시\n이름/연락처/출생년월/거주구/직업(회사/부서)/최근3년 이내 받은 시술 브랜드는?/울쎄라를 지금까지 시술받은 총횟수는?/울쎄라를 가장 최근에 시",
