      "id": "d147a41219331f46c65994717f70319b",
      "title": "11/7~9) 현재 대학생 혹은 대학원 재학 중인 남자)다양한 AI 도구를 목적에 맞게 활용하는 학생 및 스터디 그룹 조사",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/130438",
      "target_age": "",
      "target_gender": "",
      "target_condition": "으로 인터뷰를 진행하고 있습니다.",
      "date": "11월 7일(토) ~ 9일(월) 중 하루/ 오전 시간대",
      "time": "",
      "duration": "",
