      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/7~9) K-POP 팬덤 문화 및 팬 참여 트렌드 관련 전문가 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.23. 22:53\n조회 29\n구독\n11/7~9) K-POP 팬덤 문화 및 팬 참여 트렌드 관련 전문가 조사\n이번에 저희는 K-POP 팬덤 문화와 팬들의 참여 방식, 디지털 플랫폼을 통한 새로운 팬 경험 및 관련 산업 트렌드에 대한 전문적인 지식과 실무 역량을 갖춘 분들을 대상으로 인터뷰를 진행하고 있습니다.\n아래 내용에 해당되시면 신청해 주시면 고맙겠습니다.\n1. 조사대상\n- K-POP 팬덤 문화와 팬들의 행동 및 참여 트렌드를 연구, 분석하는 전문가\n* 아래 내용에 대한 전문적인 지식과 실무 역량을 갖춘 분\n1) K-POP 팬덤의 형성과 발전, 팬들의 콘텐츠 소비 및 참여 동기와 행동 특성을 전문적으로 분석할 수 있는 분\n2) 소셜미디어, 팬 커뮤니티, 팬덤 플랫폼 등에서 나타나는 팬들의 소통 방식과 팬덤 문화의 특징을 구체적으로 설명할 수 있는 분\n3) 팬들의 의견과 자발적인 활동이 아티스트의 인지도, 콘텐츠 확산 및 팬덤 문화에 미치는 영향을 분석할 수 있는 분\n4) 디지털 기술과 콘텐츠 소비 환경의 변화에 따른 팬덤 활동의 변화 및 향후 K-POP 팬덤 트렌드를 전망할 수 있는 분\n2. 조사방법과 사례\n- 방법 : 1:1 대면 인터뷰 (약 90분 이내)\n- 일시 : 11월 7일(토) ~ 9일(월) 중 하루/ 오전 시간대\n- 장소 : 서울 인근 지역\n- 사례 : 현금 50만원 계좌 입금\n3. 조사 참여신청\n- 신청양식\n이름/나이/성별/현재 소속 기관 또는 기업/직책/주요 담당 업무/K-POP 팬덤 관련 연구, 분석 분야(프로젝트명 및 담당 역할 포함)/팬덤 문화 및 팬 참여 트렌드에 대한 전문 분야\n-신청 예시\n홍길동/35세/여자/A콘텐츠연구소/선임연구원/K-POP 팬덤 문화 및 소비자 행동 연구/팬덤 플랫폼 이용 행태와 팬들의 콘텐츠 소비, 참여 동기 분석/팬덤 문화, 팬 행동 분석 및 디지털 팬덤 트렌드\n4. 대상 선정\n- 신청내용 검토 및 전화 확인을 거쳐 최종 인터뷰 대상자를 선정합니다.\nhttps://forms.gle/fp8JRDKikmmJboyE7\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n11/7~9)K-POP 팬덤 마케팅 및 팬 참여형 콘텐츠 관련 실무자 조사\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n11/7~9) K-POP 팬덤 문화 및 팬 참여 트렌드 관련 전문가 조사\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n11/7~9) K-뷰티 개인 맞춤형 서비스 및 디지털 기술 관련 전문가 조사\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n11/7~9) 현재 대학생 혹은 대학원 재학 중인 여성)다양한 AI 도구를 목적에 맞게 활용하는 학생 및 스터디 그룹 조사\n좌담회알바좌담회카페\n26.10.23.\n댓글\n0\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
