      "location": "청담역 인근 키즈카페",
      "type": "맛테스트",
      "raw_content": "팬티형 기저귀 착용 테스트 및 자녀 동반 인터뷰-9~16kg 자녀와 어머니 11/5[23만원]\n​\n★모모래빗★ 5단계 팬티형 기저귀(일반라인) 주사용자가 필요합니다.\n모모래빗 에코씽씽 팬티\n모모래빗 에코드라이 팬티\n모모래빗 에코컴포트핏 팬티\n모모래빗 에코드라이 썸머 팬티\n​\n대상 : 체중 9~16kg 자녀를 둔 어머니\n팸퍼스 또는 하기스 팬티형 기저귀 주사용자\n대형(L, 4단계) 또는 특대형(Extra Large, 5단계) 사용자\n어머니가 하루 평균 기저귀를 5개 이상 직접 교체하는 분\n자택 및 자녀방 공개와 기저귀 교체 과정 촬영에 동의하는 분\n현재 사용하는 기저귀 사진을 사전에 제출할 수 있는 분\n일정 : 11/5(목)\n오전 11시~오후 3시\n오후 12시~4시\n오후 1시~5시\n방법 : 기저귀 사전 착용 테스트 + 모바일 설문 + 자녀 동반 인터뷰\n소요시간 : 사전 모바일 설문 1일 약 5분 이내\n당일 인터뷰 약 4시간\n사례비 : 230,000원\n최종 인터뷰까지 참여한 경우에만 지급\n참여 이후 본인 계좌이체 예정\n기타소득신고를 위한 개인정보 입력 필수\n장소 : 청담역 인근 키즈카페\n조사 진행 안내\n1. 조사 전전날 & 전날\n2개의 테스트 기저귀를 1일씩 착용해보면서 모바일 설문 작성(5분 이내)\n테스트 제품은 택배 발송 예정\n2. 조사 당일\n테스트 기저귀를 착용한 상태로 도착하여 진행 중간마다 다른 기저귀로 교체 테스트를 하면서 인터뷰 진행\n자녀가 키즈카페에서 놀다가 기저귀를 교체하는 방식으로 해당 상황을 촬영하고 인터뷰를 진행합니다.\n이는 기저귀를 착용하는 방식, 착용 전후의 전반적 상태 등을 알아보기 위함입니다.\n3. 진행과정\n대상자 선정통화(15~20분) → 최종인터뷰 참석확정연락 → 기저귀 테스트제품 사전착용 및 모바일설문 작성 → 자녀 동반 인터뷰 최종참석\n※ 현 주사용 제품은 사전에 사진으로 확인합니다.\n※ 조사방식을 모두 준수하실 수 있는 분들만 신청 부탁드립니다.\n​\n신청하기",
